#!/usr/bin/env bun
// @io-wall-ok — composition root
/**
 * Graphify skill install (`bun run graphify:install`, run once by a cold
 * workspace's preparation in `libs/tools-harness-ts/workspace/run.sh`).
 *
 * Graphify (`pipx:graphifyy` in `mise.toml`) turns the repo into a knowledge
 * graph that `graphify query` / `path` / `explain` answer from. Its agent skill
 * (`/graphify` in Claude Code, `$graphify` in Codex) is generated by the
 * pinned release, so it is gitignored and written here, never committed:
 *
 * - `.agents/skills/graphify` is the project skill Codex reads.
 * - `.claude/skills/graphify` is a symlink to it for Claude Code, the same
 *   shape every other skill in `.claude/skills` has.
 *
 * Graphify's own hooks are not installed: the git hooks are banned
 * (AGENTS.md), and its agent hooks hard-code one laptop's mise path. The
 * guidance for both agents is the Graphify section of `AGENTS.md`.
 *
 * Without Graphify on the machine (a CI job that installs a smaller toolchain)
 * this prints a note and exits 0: install must not fail on an optional tool.
 */
import {
  existsSync,
  lstatSync,
  mkdirSync,
  readlinkSync,
  symlinkSync,
} from 'node:fs';
import { dirname, join } from 'node:path';
import { removeTree } from '@pkgs/os-server-ts/remove-tree';
import { slashPath } from '@pkgs/os-shared-ts/slash-path';

const ROOT = join(import.meta.dirname, '../../..');

/** The skill directory graphify writes for `--platform agents`. */
export const SKILL_DIR = '.agents/skills/graphify';

/** Claude Code's entry for the same skill, relative to its own directory. */
export const CLAUDE_SKILL_LINK = '.claude/skills/graphify';

export function graphifyInstallCommand(graphify: string): readonly string[] {
  return [graphify, 'install', '--project', '--platform', 'agents'];
}

/** The symlink target for {@link CLAUDE_SKILL_LINK}, from its directory. */
export function claudeSkillTarget(): string {
  const depth = dirname(CLAUDE_SKILL_LINK).split('/').length;
  return `${'../'.repeat(depth)}${SKILL_DIR}`;
}

function resolveGraphify(): string | undefined {
  const onPath = Bun.which('graphify');
  if (onPath !== null) return onPath;
  const viaMise = Bun.spawnSync(['mise', 'which', 'graphify'], {
    cwd: ROOT,
    stderr: 'ignore',
  });
  return viaMise.exitCode === 0 ? viaMise.stdout.toString().trim() : undefined;
}

function linkClaudeSkill(): void {
  const link = join(ROOT, CLAUDE_SKILL_LINK);
  const target = claudeSkillTarget();
  if (existsSync(link) || isSymlink(link)) {
    if (isSymlink(link) && slashPath(readlinkSync(link)) === target) return;
    removeTree(link);
  }
  mkdirSync(dirname(link), { recursive: true });
  symlinkSync(target, link);
}

function isSymlink(path: string): boolean {
  try {
    return lstatSync(path).isSymbolicLink();
  } catch {
    return false;
  }
}

if (import.meta.main) {
  const graphify = resolveGraphify();
  if (graphify === undefined) {
    console.log('graphify:install: graphify not installed; run `mise install`');
  } else {
    const result = Bun.spawnSync([...graphifyInstallCommand(graphify)], {
      cwd: ROOT,
      stdio: ['inherit', 'inherit', 'inherit'],
    });
    if (result.exitCode !== 0) {
      console.error('graphify:install: ERROR: `graphify install` failed');
      process.exit(result.exitCode ?? 1);
    }
    linkClaudeSkill();
  }
}
